<main class="px-4 py-8 sm:px-6 lg:px-10"><div class="mx-auto max-w-7xl space-y-6"><section class="glass-3 rounded-2xl p-6"><p class="text-primary text-xs font-bold uppercase tracking-[0.2em]">MIPG</p><h1 class="mt-2 text-3xl font-bold text-gray-900">Seguimiento</h1><p class="mt-2 text-sm text-gray-600">Pendientes, revisiones y alertas de implementación.</p></section><section class="grid gap-4 sm:grid-cols-3">{#each [['Pendientes', 7], ['En revisión', 4], ['Vencidas', 2]] as item (item[0])}<article class="glass-3 rounded-xl p-5"><p class="text-xs text-gray-500">{item[0]}</p><p class="mt-2 text-3xl font-bold text-gray-900">{item[1]}</p></article>{/each}</section><section class="glass-3 rounded-xl p-6"><h2 class="text-xl font-semibold text-gray-900">Mis tareas</h2><div class="mt-5 grid gap-3 md:grid-cols-2">{#each mipgTasks as task (task.title)}<article class="rounded-xl border border-gray-200/70 bg-white/55 p-4"><div class="flex items-start justify-between gap-3"><h3 class="text-sm font-semibold text-gray-800">{task.title}</h3><span class="rounded-full bg-orange-100 px-2 py-1 text-xs font-semibold text-orange-700">{task.state}</span></div><p class="mt-2 text-xs text-gray-500">{task.owner} · {task.due}</p><button type="button" class="text-primary mt-4 text-xs font-semibold hover:underline">Abrir tarea</button></article>{/each}</div></section></div></main>
